    <button class="tool-btn btn">☷</button><button class="tool-btn btn">☷</button><button class="tool-btn selected btn">☷</button>
    <button class="tool-btn btn">−</button><button class="tool-btn btn">＝</button><button class="tool-btn selected btn">≡</button><button class="tool-btn btn">↗</button>
